package sem

import (
	"strings"
	"testing"
)

// Swift call idioms the generic scanners miss (evidence: on apple/swift-nio the
// focus method ByteBuffer.discardReadBytes resolved 0/3 inbound CALLS edges):
// labeled/inout parameters (`remainder buffer: inout ByteBuffer`), enum-case
// pattern bindings dispatched inside a defer block (`case .available(var
// buffer):` ... `defer { buffer.discardReadBytes() }`), and force-unwrapped
// optional stored-property receivers (`self._buffer!.discardReadBytes()`).
func TestSwiftReceiverTypedCallIdioms(t *testing.T) {
	repo := t.TempDir()
	writeFile(t, repo, "Sources/NIOCore/ByteBuffer-core.swift", `public struct ByteBuffer {
    internal var _readerIndex: Int = 0

    @discardableResult
    public mutating func discardReadBytes() -> Bool {
        guard self._readerIndex > 0 else {
            return false
        }
        return true
    }
}
`)
	writeFile(t, repo, "Sources/NIOCore/Codec.swift", `struct B2MDBuffer {
    enum BufferAvailability {
        case bufferAlreadyBeingProcessed
        case nothingAvailable
        case available(ByteBuffer)
    }

    private var buffers: [ByteBuffer] = []

    func startProcessing(allowEmptyBuffer: Bool) -> BufferAvailability {
        return .nothingAvailable
    }

----
// half shipped at revision 3, so a build carrying only that half wrote records
// under the revision-3 namespace with these four languages still phantom-laden.
// Landing this correction at revision 3 would serve those records back and the
// fix would be invisible for exactly the languages it covers, so it takes its
// own bump.
func TestRemainingNestedCallableCorrectionsAreRevisioned(t *testing.T) {
	for _, testCase := range []struct {
		language  string
		path      string
		src       string
		corrected string
		phantom   string
	}{{
		language:  "Swift",
		path:      "c.swift",
		src:       "class C {\n    func m() -> Int {\n        func helper(_ v: Int) -> Int {\n            return v\n        }\n        return helper(1)\n    }\n}\n",
		corrected: "local/example:Swift:c.swift:function:C.m.helper",
		phantom:   "local/example:Swift:c.swift:method:C.helper",
	}, {
		language:  "Kotlin",
		path:      "c.kt",
		src:       "class C {\n    fun m(): Int {\n        fun helper(v: Int): Int {\n            return v\n        }\n        return helper(1)\n    }\n}\n",
		corrected: "local/example:Kotlin:c.kt:function:C.m.helper",
		phantom:   "local/example:Kotlin:c.kt:method:C.helper",
	}, {
		language:  "Rust",
		path:      "c.rs",
		src:       "impl C {\n    pub fn m(&self) -> i32 {\n        fn helper(v: i32) -> i32 {\n            v\n        }\n        helper(1)\n    }\n}\n",
		corrected: "local/example:Rust:c.rs:function:C.m.helper",
		phantom:   "local/example:Rust:c.rs:method:C.helper",
	}, {
